import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  const [showProfile, setShowProfile] = useState(false);
  const [showTheme, setShowTheme] = useState(false);

  const [profile, setProfile] = useState({
    name: "User",
    email: "user@email.com"
  });

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("profile"));
    if (saved) setProfile(saved);
  }, []);

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div>
            <div className="logo">FinSight</div>
            <div style={{ fontSize: "13px", color: "#6b7280" }}>
              Personal Expense Intelligence
            </div>
          </div>

          <div className="nav-actions">

            {/* TABS */}
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "history" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("history")}
              >
                History
              </span>
            </div>

            {/* PROFILE ICON */}
            <div
              onClick={() => {
                setShowProfile(!showProfile);
                setShowTheme(false);
              }}
              style={{
                width: "36px",
                height: "36px",
                borderRadius: "50%",
                background: "linear-gradient(135deg,#4f6df5,#6a85ff)",
                color: "#fff",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: "pointer",
                marginLeft: "10px",
                fontSize: "14px"
              }}
            >
              {profile.name.charAt(0).toUpperCase()}
            </div>

            {/* ✅ NEW SPLIT THEME ICON */}
            <div
              onClick={() => {
                setShowTheme(!showTheme);
                setShowProfile(false);
              }}
              style={{
                width: "28px",
                height: "28px",
                borderRadius: "50%",
                marginLeft: "10px",
                cursor: "pointer",
                background: "linear-gradient(to right, #ffffff 50%, #111827 50%)",
                border: "1px solid #d1d5db"
              }}
            ></div>

          </div>
        </div>

        {/* THEME DROPDOWN */}
        {showTheme && (
          <div style={{
            position: "absolute",
            top: "70px",
            right: "20px",
            background: "#111",
            color: "#fff",
            borderRadius: "14px",
            padding: "12px",
            width: "160px"
          }}>
            <div
              style={{ padding: "8px", cursor: "pointer" }}
              onClick={() => {
                setDarkMode(false);
                setShowTheme(false);
              }}
            >
              ☀️ Light
            </div>

            <div
              style={{ padding: "8px", cursor: "pointer" }}
              onClick={() => {
                setDarkMode(true);
                setShowTheme(false);
              }}
            >
              🌙 Dark
            </div>
          </div>
        )}

        {/* HERO */}
        <div className="hero">
          <h1>
            Welcome, <span style={{ color: "#4f6df5" }}>{profile.name}</span>
          </h1>
        </div>

      </div>
    </div>
  );
}

export default Dashboard;
